const dicts: Record<Lang, Record<Key, string>> = { he, en };
let lang: Lang = "he";
export const setLang = (l: Lang) => { lang = l; document.documentElement.lang = l; document.documentElement.dir = l === "he" ? "rtl" : "ltr"; };
export const getLang = () => lang;
export function t(key: Key, vars?: Record<string, string | number>): string {
  let s = dicts[lang][key] ?? he[key];
  // באנגלית: שם בעברית (רשת, סניף, עיר) בתוך משפט משמאל לימין מתהפך ("₪82.64 ,יוחננוף").
  // עוטפים ערכים עם אותיות עבריות ב-FSI/PDI (בידוד כיווניות) — בלתי נראה, ומונע את ההיפוך.
  const iso = (v: string) => (lang !== "he" && /[֐-׿]/.test(v) ? `⁨${v}⁩` : v);
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(iso(String(v)));
  return s;
}
export type { Key };
